using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Playables;using UnityEngine.Animations;using Unity.DemoTeam.Hair;using Sandbox.CharacterSystem;using Newtonsoft.Json;
public static class RenderLioraCandidate {
 const string Output="Data/Liora/Integration/Previews/";
 static Mesh Snapshot(SkinnedMeshRenderer r,Transform root){
 var source=r.sharedMesh;var p=source.vertices;var n=source.normals;var t=source.tangents;var dp=new Vector3[p.Length];var dn=new Vector3[p.Length];var dt=new Vector3[p.Length];
 for(int s=0;s<source.blendShapeCount;s++){float w=r.GetBlendShapeWeight(s)*.01f;if(w==0)continue;source.GetBlendShapeFrameVertices(s,0,dp,dn,dt);for(int j=0;j<p.Length;j++){p[j]+=dp[j]*w;n[j]+=dn[j]*w;if(t.Length>0)t[j]+=new Vector4(dt[j].x,dt[j].y,dt[j].z,0)*w;}}
 var matrices=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*source.bindposes[j]).ToArray();var normalMatrices=matrices.Select(m=>m.inverse.transpose).ToArray();var op=new Vector3[p.Length];var on=new Vector3[p.Length];var ot=new Vector4[p.Length];
 using(var counts=source.GetBonesPerVertex())using(var weights=source.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++){Vector3 tangent=Vector3.zero;for(int k=0;k<counts[j];k++){var w=weights[at++];op[j]+=matrices[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;on[j]+=normalMatrices[w.boneIndex].MultiplyVector(n[j])*w.weight;if(t.Length>0)tangent+=matrices[w.boneIndex].MultiplyVector(t[j])*w.weight;}on[j].Normalize();tangent.Normalize();if(t.Length>0)ot[j]=new Vector4(tangent.x,tangent.y,tangent.z,t[j].w);}}
 var mesh=new Mesh{name="Snapshot "+r.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.vertices=op;mesh.normals=on;if(t.Length>0)mesh.tangents=ot;mesh.uv=source.uv;mesh.uv2=source.uv2;mesh.subMeshCount=source.subMeshCount;for(int j=0;j<source.subMeshCount;j++)mesh.SetTriangles(source.GetTriangles(j),j);mesh.RecalculateBounds();return mesh;
 }
 static Mesh Scalp(HairAsset.StrandGroup group){
 var p=new List<Vector3>();var n=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();
 for(int strand=0;strand<group.strandCount;strand+=5){HairAssetUtility.DeclareStrandIterator(group,strand,out int start,out int step,out int end);int offset=p.Count;for(int j=0;j<32;j++){
 var center=group.particlePosition[start+j*step];var before=group.particlePosition[start+Mathf.Max(0,j-1)*step];var after=group.particlePosition[start+Mathf.Min(31,j+1)*step];var tangent=(after-before).normalized;var side=Vector3.Cross(tangent,Vector3.forward).normalized;if(side.sqrMagnitude<.01f)side=Vector3.right;float radius=.000065f*(1-.7f*j/31f);p.Add(center-side*radius);p.Add(center+side*radius);n.Add(-Vector3.forward);n.Add(-Vector3.forward);uv.Add(new Vector2(0,j/31f));uv.Add(new Vector2(1,j/31f));if(j<31){int a=offset+j*2;tri.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}}
 }var m=new Mesh{name="Static review scalp (one fifth of strands)",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};m.SetVertices(p);m.SetNormals(n);m.SetUVs(0,uv);m.SetTriangles(tri,0);m.RecalculateBounds();return m;
 }
 public static object Run(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");Directory.CreateDirectory(Output);
 var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Liora/Candidate/Liora_Candidate.prefab");var scene=EditorSceneManager.NewPreviewScene();var resources=new List<UnityEngine.Object>();
 try{
 var cg=new GameObject("Liora review camera");SceneManager.MoveGameObjectToScene(cg,scene);var camera=cg.AddComponent<Camera>();camera.scene=scene;camera.cameraType=CameraType.Preview;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.14f,.16f,.19f);camera.orthographic=true;camera.nearClipPlane=.01f;camera.farClipPlane=10;
 foreach(var pair in new[]{(rotation:new Vector3(25,155,0),intensity:1.5f),(rotation:new Vector3(-15,215,0),intensity:.8f)}){var go=new GameObject("Review light");SceneManager.MoveGameObjectToScene(go,scene);var light=go.AddComponent<Light>();light.type=LightType.Directional;light.intensity=pair.intensity;light.cullingMask=1<<30;go.transform.rotation=Quaternion.Euler(pair.rotation);}
 var animator=root.GetComponentInChildren<Animator>(true);var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="BAKED_head_lod0_mesh");var head=animator.GetBoneTransform(HumanBodyBones.Head);var hair=root.GetComponentInChildren<HairInstance>(true);var scalp=Scalp(hair.strandGroupProviders[0].hairAsset.strandGroups.Single());resources.Add(scalp);
 var scalpMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));resources.Add(scalpMat);scalpMat.SetColor("_BaseColor",new Color(.055f,.026f,.015f));scalpMat.SetFloat("_Smoothness",.25f);scalpMat.SetFloat("_Cull",0);
 var rest=root.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));var files=new List<string>();
 foreach(var pose in new[]{"Neutral","Blink","BrowRaised","Joy","Speech","ThreeQuarter","Waving","Talking","Thinking"}){
 foreach(var p in rest){p.Key.localPosition=p.Value.Item1;p.Key.localRotation=p.Value.Item2;p.Key.localScale=p.Value.Item3;}foreach(var r in root.GetComponentsInChildren<SkinnedMeshRenderer>(true))for(int s=0;s<r.sharedMesh.blendShapeCount;s++)r.SetBlendShapeWeight(s,0);
 Action<string,float> set=(name,weight)=>face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex(name),weight);
 if(pose=="Blink"){set("eyeBlinkLeft",100);set("eyeBlinkRight",100);}if(pose=="BrowRaised"){set("browInnerUp",100);set("browOuterUpLeft",100);set("browOuterUpRight",100);}if(pose=="Joy")set("emo_joy",100);if(pose=="Speech"){set("viseme_aa",65);set("mouthSmileLeft",20);set("mouthSmileRight",20);}root.GetComponent<CharacterFacialMeshSync>().Apply();
 bool motion=new[]{"Waving","Talking","Thinking"}.Contains(pose);if(motion){var def=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox/Data"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).First(d=>d&&d.name==pose);var graph=PlayableGraph.Create("Liora static review pose");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,def.Clip);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"pose",animator).SetSourcePlayable(p);graph.Play();p.SetTime(def.Clip.length*.45);graph.Evaluate(0);}finally{graph.Destroy();}}
 var objects=new List<GameObject>();var meshes=new List<Mesh>();
 try{
 foreach(var r in root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.enabled)){var mesh=Snapshot(r,root.transform);meshes.Add(mesh);var go=new GameObject("Frozen "+r.name);SceneManager.MoveGameObjectToScene(go,scene);go.layer=30;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;objects.Add(go);}
 var h=new GameObject("Scalp review proxy");SceneManager.MoveGameObjectToScene(h,scene);h.layer=30;h.transform.SetPositionAndRotation(head.position,head.rotation);h.AddComponent<MeshFilter>().sharedMesh=scalp;h.AddComponent<MeshRenderer>().sharedMaterial=scalpMat;objects.Add(h);
 var center=motion?new Vector3(0,.9f,0):new Vector3(0,1.61f,0);camera.orthographicSize=motion?.94f:.22f;camera.transform.position=center+(pose=="ThreeQuarter"?new Vector3(1.4f,.1f,3):Vector3.forward*3);camera.transform.LookAt(center);
 int width=motion?768:768,height=motion?1024:900;var rt=RenderTexture.GetTemporary(width,height,24);var previous=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(width,height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();string file=Output+pose+".png";File.WriteAllBytes(file,tex.EncodeToPNG());files.Add(file);UnityEngine.Object.DestroyImmediate(tex);}finally{camera.targetTexture=null;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}
 }finally{foreach(var o in objects)UnityEngine.Object.DestroyImmediate(o);foreach(var m in meshes)UnityEngine.Object.DestroyImmediate(m);}
 }
 var report=new{files,staticMeshReview=true,scalpPreview="One fifth of authored strands as static ribbons, all 32 points; production groom density unchanged",simulationTested=false,sceneSaved=false};File.WriteAllText("Data/Liora/Integration/render_review.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{images=files.Count};
 }finally{PrefabUtility.UnloadPrefabContents(root);EditorSceneManager.ClosePreviewScene(scene);foreach(var o in resources)if(o)UnityEngine.Object.DestroyImmediate(o);}
 }
}
